{{ define "main" }}
<main class="container py-4">

  <header class="mb-4">
    <h1 class="mb-1">{{ .Title }}</h1>
    {{ with .Content }}
      <div class="section-intro">
        {{ . }}
      </div>
    {{ end }}
  </header>

  {{/* Collect all publication pages in this site */}}
  {{ $pubPages := where .Site.RegularPages "Section" "publication" }}

  {{ if gt (len $pubPages) 0 }}

    {{/* Group by year (YYYY) and sort years descending */}}
    {{ $groups := $pubPages.GroupByDate "2006" }}
    {{ range sort $groups "Key" "desc" }}
      {{ $year := .Key }}

      <section class="pub-year" id="pub-{{ $year }}">
        <h2 class="pub-year-heading">{{ $year }}</h2>

        <ul class="pub-list">
          {{/* Sort publications within the year by date desc */}}
          {{ range sort .Pages "Date" "desc" }}
            {{ $p := . }}

            <li class="pub-item">

              {{/* ── Title (links to PDF if available, otherwise plain) ── */}}
              {{ $pdf := "" }}
              {{ with $p.Params.url_pdf }}
                {{ $pdf = . }}
              {{ end }}
              {{ if eq $pdf "" }}
                {{ with $p.Resources.GetMatch "*.pdf" }}
                  {{ $pdf = .RelPermalink }}
                {{ end }}
              {{ end }}

              {{ if ne $pdf "" }}
                {{ $isAbs := or (hasPrefix $pdf "http") (hasPrefix $pdf "/") }}
                {{ $href := cond $isAbs $pdf (printf "%s%s" $p.RelPermalink $pdf) }}
                <a class="pub-title" href="{{ $href }}">{{ $p.Title }}</a>
              {{ else }}
                <span class="pub-title">{{ $p.Title }}</span>
              {{ end }}

              {{/* ── Authors ── */}}
              {{ with $p.Params.authors }}
                <span class="pub-authors">{{ delimit . ", " }}</span>
              {{ end }}

              {{/* ── Venue + Award (inline) ── */}}
              {{ with $p.Params.publication }}
                <span class="pub-venue">
                  {{ . }}
                  {{ with $p.Params.award }}
                    <span class="pub-award-badge">🏆 {{ . }}</span>
                  {{ end }}
                </span>
              {{ end }}

              {{/* ── Action links (plain text style) ── */}}
              {{ $hasLinks := false }}
              <span class="pub-links">
                {{ if ne $pdf "" }}
                  {{ $isAbs := or (hasPrefix $pdf "http") (hasPrefix $pdf "/") }}
                  {{ $href := cond $isAbs $pdf (printf "%s%s" $p.RelPermalink $pdf) }}
                  <a href="{{ $href }}">[Paper]</a>
                  {{ $hasLinks = true }}
                {{ end }}
                {{ with $p.Params.url_code }}
                  <a href="{{ . }}">[Code]</a>
                  {{ $hasLinks = true }}
                {{ end }}
                {{ with $p.Params.url_slides }}
                  <a href="{{ . }}">[Slides]</a>
                  {{ $hasLinks = true }}
                {{ end }}
                {{ with $p.Params.url_video }}
                  <a href="{{ . }}">[Video]</a>
                  {{ $hasLinks = true }}
                {{ end }}
              </span>

              {{/* ── Abstract toggle (kept) ── */}}
              {{ $abs := "" }}
              {{ with $p.Params.abstract }}
                {{ $abs = . }}
              {{ end }}
              {{ if eq $abs "" }}
                {{ with $p.Params.summary }}
                  {{ $abs = . }}
                {{ end }}
              {{ end }}
              {{ if eq $abs "" }}
                {{ with $p.Summary }}
                  {{ $abs = . }}
                {{ end }}
              {{ end }}

              {{ if ne $abs "" }}
                {{ $html := $abs | markdownify }}
                {{ if in $html "<details" }}
                  {{ $html | safeHTML }}
                {{ else }}
                  <details class="pub-abstract">
                    <summary>Abstract</summary>
                    <div class="abstract-content">
                      {{ $html | safeHTML }}
                    </div>
                  </details>
                {{ end }}
              {{ end }}

            </li>
          {{ end }}
        </ul>
      </section>

    {{ end }}

  {{ else }}
    <p>No publications yet.</p>
  {{ end }}

</main>
{{ end }}

