{{ define "main" }}
<main id="people">
  <div class="container">
    <h1>{{ .Title }}</h1>

    {{ $authorsSection := site.GetPage "section" "authors" }}
    {{ if not $authorsSection }}
      <p>No <code>content/authors</code> section found.</p>
    {{ else }}

      {{/* ── "Our Group" – Faculty first, then students (sorted by last name) ── */}}
      {{ $faculty := where $authorsSection.Pages "Params.user_groups" "intersect" (slice "Faculty") }}
      {{ $students := where $authorsSection.Pages "Params.user_groups" "intersect" (slice "Lab Member") }}
      {{ if or (gt (len $faculty) 0) (gt (len $students) 0) }}
        <section class="people-section-group">
          <h2 class="people-section-heading">Our Group</h2>
          <div class="people-listing layout-hover">
            {{/* Faculty first */}}
            {{ range $faculty }}
              <div class="people-item">
                {{ with .Resources.GetMatch "avatar*" }}
                  <img src="{{ .RelPermalink }}" alt="{{ $.Title }}" class="people-avatar" />
                {{ end }}
                <div class="people-info">
                  <h5 class="people-name">
                    <a href="{{ .RelPermalink }}">{{ .Title }}</a>
                  </h5>
                  {{ with .Params.role }}
                    <p class="people-role">{{ . }}</p>
                  {{ end }}
                </div>
              </div>
            {{ end }}
            {{/* Then students sorted by last name */}}
            {{ range sort $students "Params.last_name" }}
              <div class="people-item">
                {{ with .Resources.GetMatch "avatar*" }}
                  <img src="{{ .RelPermalink }}" alt="{{ $.Title }}" class="people-avatar" />
                {{ end }}
                <div class="people-info">
                  <h5 class="people-name">
                    <a href="{{ .RelPermalink }}">{{ .Title }}</a>
                  </h5>
                  {{ with .Params.role }}
                    <p class="people-role">{{ . }}</p>
                  {{ end }}
                </div>
              </div>
            {{ end }}
          </div>
        </section>
      {{ end }}

      {{/* ── Alumni sections ── */}}
      {{ $alumniSections := slice
        (dict "key" "Postdoc Alumni"       "label" "Postdoc Alumni")
        (dict "key" "PhD Alumni"           "label" "PhD Alumni")
        (dict "key" "Masters Alumni"       "label" "Masters Alumni")
        (dict "key" "Undergraduate Alumni" "label" "Undergraduate Alumni")
      }}

      {{ range $section := $alumniSections }}
        {{ $members := where $authorsSection.Pages "Params.user_groups" "intersect" (slice $section.key) }}
        {{ if gt (len $members) 0 }}
          <section class="people-section-group">
            <h2 class="people-section-heading">{{ $section.label }}</h2>
            <div class="people-listing layout-minimal">
              {{ range sort $members "Params.last_name" }}
                <div class="people-item">
                  {{ with .Resources.GetMatch "avatar*" }}
                    <img src="{{ .RelPermalink }}" alt="{{ $.Title }}" class="people-avatar" />
                  {{ end }}
                  <div class="people-info">
                    <h5 class="people-name">
                      <a href="{{ .RelPermalink }}">{{ .Title }}</a>
                    </h5>
                    {{ with .Params.role }}
                      <p class="people-role">{{ . }}</p>
                    {{ end }}
                  </div>
                </div>
              {{ end }}
            </div>
          </section>
        {{ end }}
      {{ end }}

    {{ end }}
  </div>
</main>
{{ end }}

